        elif kind == "touch":
            os.utime(full, (op["m"], op["m"]))
        elif kind == "touchall":
            if os.path.isdir(full):
                for d, dns, fns in os.walk(full, topdown=False):
                    for n in fns + dns:
                        q = os.path.join(d, n)
                        if not os.path.islink(q):
                            os.utime(q, (op["m"], op["m"]))
                os.utime(full, (op["m"], op["m"]))
            elif os.path.exists(full):
